{
     "title": "CSCI-518: Collaborative Seminar in Computer Graphics",
     "learningObjectives": [
       "Define the standard stages of the OpenGL graphics pipeline and their sequential processing order.",
       "Explain how geometric transformations and viewing models map 3D scene data to a 2D pixel grid.",
       "Evaluate visual correctness by identifying how sampling decisions, shading models, and coordinate spaces impact rendering outcomes."
     ],
     "beats": [
       {
         "title": "Pipeline Foundation",
         "claim": "The OpenGL graphics pipeline processes vertices through programmable shader stages.",
         "example": "Vertex data enters the pipeline first, where vertex shaders modify position, color, or normal attributes before downstream stages.",
         "visualDirection": "Display a left-to-right flowchart showing vertex input → vertex shader → primitive assembly → clipping → rasterization → fragment shader → framebuffer.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Primitive Assembly",
         "claim": "Primitive assembly groups vertices into points, lines, or triangles.",
         "example": "Three connected vertices form a triangle primitive, which the pipeline then processes as a single geometric unit for rendering.",
         "visualDirection": "Show a wireframe triangle with labeled vertices, highlighting how three points are bound into a single primitive before clipping.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Clipping Stage",
         "claim": "Clipping removes portions outside the view volume.",
         "example": "A triangle extending beyond the camera's frustum is sliced at the clipping plane boundaries, discarding the exterior segments.",
         "visualDirection": "Illustrate a 3D cube partially outside a transparent viewing box, with clipped edges highlighted in red and retained portions in blue.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Rasterization",
         "claim": "Rasterization converts primitives into fragment candidates.",
         "example": "Each triangle is subdivided into pixel-aligned fragments, with each fragment receiving interpolated attributes for downstream processing.",
         "visualDirection": "Render a grid overlay on a triangle, showing how each pixel cell becomes a fragment candidate with assigned vertex attributes.",
         "sourceIds": ["khronos-opengl", "mit-computer-graphics"]
       },
       {
         "title": "Interpolation",
         "claim": "Interpolation produces per-fragment values from vertex outputs.",
         "example": "Color and normal values are linearly interpolated across a triangle's pixels using barycentric coordinates to ensure smooth shading.",
         "visualDirection": "Display a color gradient across a triangle, with interpolation weights labeled at each vertex and midpoint to show value distribution.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Fragment Processing",
         "claim": "Fragment processing computes values for framebuffer operations.",
         "example": "Fragment shaders evaluate lighting equations and material properties to generate final color and alpha values for each pixel.",
         "visualDirection": "Show a side-by-side comparison of a raw triangle mesh and its shaded output, with a callout box explaining the fragment shader's role.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Depth Testing",
         "claim": "Depth testing resolves visibility according to stored depth values.",
         "example": "Each fragment's depth value is compared against the depth buffer; fragments with greater depth are discarded to maintain correct occlusion.",
         "visualDirection": "Illustrate two overlapping triangles with depth values, highlighting the front triangle as retained and the back triangle as rejected by depth testing.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Blending",
         "claim": "Blending combines a fragment result with an existing framebuffer value.",
         "example": "Translucent surfaces blend the new fragment's color with the underlying color using alpha values to produce semi-transparent overlays.",
         "visualDirection": "Render a semi-transparent square over a solid background, with a legend showing the blending equation and resulting composite color.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Coordinate Spaces",
         "claim": "Coordinate spaces, sampling, and numerical precision must remain explicit.",
         "example": "Explicitly defining vertex, fragment, and texture coordinate spaces prevents misalignment during sampling and ensures consistent precision across pipeline stages.",
         "visualDirection": "Display a diagram of three nested coordinate spaces (world, view, clip) with labeled axes, emphasizing explicit mapping between them.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Practical Analysis Checklist",
         "claim": "Visual correctness follows from explicit conventions, assumptions, sampling decisions, and measurable error.",
         "example": "Instructor-led review checks that coordinate mappings are explicit, sampling rates match resolution requirements, and error bounds remain within acceptable thresholds.",
         "visualDirection": "Show a checklist graphic with four boxes: explicit conventions, sampling decisions, measurable error, and coordinate space alignment, each with a tick mark for verification.",
         "sourceIds": ["mit-computer-graphics"]
       }
     ]
   }
